<template>
  <view class="profile-container">
    <!-- 顶部导航栏 -->
    <view class="nav-header">
      <view class="left-btn" @click="goBack">返回</view>
      <text class="header-title">个人信息</text>
      <view class="right-placeholder"></view>
    </view>
	
	<!-- 用户基本信息 -->
	<view class="user-info">
	  <!-- 头像选择 -->
	  <button 
	    class="avatar-wrapper"
	    open-type="chooseAvatar" 
	    @chooseavatar="onChooseAvatar"
	  >
	    <image 
	      v-if="tempUserInfo.avatar"
	      :src="tempUserInfo.avatar"
	      class="avatar-image"
	      mode="aspectFill"
	    />
	    <view v-else class="avatar-placeholder">
	      <text>头像</text>
	    </view>
	  </button>
	
	  <!-- 昵称输入 -->
	  <input 
	    type="nickname"
	    v-model="tempUserInfo.nickname"
	    :placeholder="showNicknameTip ? '请输入昵称' : defaultNickname"
	    @change="onNicknameChange"
	    class="nickname-input"
	    :class="{ 'highlight': showNicknameTip }"
	  />
	</view>
	
	<!-- 提示信息 -->
	<view v-if="showNicknameTip" class="tip-text">
	  请设置昵称
	</view>

    <!-- 表单区域 -->
    <view class="form-section">
      <view class="form-title">请填写基本信息</view>
      <view class="form-item">
        <text class="label">年龄<text class="required">*</text></text>
        <picker 
          mode="selector" 
          :range="ageRange" 
          :value="ageIndex"
          @change="onAgeChange"
        >
          <view class="picker-value">
            {{ formData.age || '请选择年龄' }}
          </view>
        </picker>
      </view>

      <view class="form-item">
        <text class="label">公司<text class="required">*</text></text>
        <input 
          class="input" 
          v-model="formData.company" 
          placeholder="真实的公司名才有诚意"
        />
      </view>

      <view class="form-item">
        <text class="label">岗位</text>
        <input 
          class="input" 
          v-model="formData.position" 
          placeholder="不然大家开口都称你老师"
        />
      </view>

      <view class="form-item">
        <text class="label">毕业院校<text class="required">*</text></text>
        <input 
          class="input" 
          v-model="formData.school" 
          placeholder="大神毕业于哪里，让小弟膜拜下"
        />
      </view>

      <view class="form-item">
        <text class="label">个人介绍</text>
        <textarea 
          class="textarea" 
		  maxlength="3000"
          v-model="formData.introduction" 
          placeholder="介绍一下自己吧"
        />
      </view>
    </view>

    <!-- 保存按钮 -->
    <button 
      class="save-btn" 
      @click="saveProfile" 
      :disabled="isSaving"
    >{{ isSaving ? '保存中...' : '保存' }}</button>
  </view>
</template>

<script>
import userApi from '@/request/api/user'

export default {
  data() {
    return {
	  defaultNickname: '用户名XXX',
	  tempUserInfo: {
	    avatar: '',
	    nickname: '',
		avatarBase64: ''
	  },
	  showNicknameTip: false,
      formData: {
        avatar: '',
        age: '',
        company: '',
        position: '',
        school: '',
        introduction: ''
      },
      ageRange: Array.from({length: 100}, (_, i) => i + 1),
      ageIndex: 0,
      isSaving: false,
      isEdit: false
    }
  },

  onLoad() {
    this.loadUserProfile()
  },

  methods: {
	  // 头像选择回调
	  async onChooseAvatar(e) {
	    if (e.detail.avatarUrl) {
	      try {
	        uni.showLoading({
	          title: '处理中...'
	        })
	        
	        // 更新临时头像显示
	        this.tempUserInfo.avatar = e.detail.avatarUrl
	        // 显示昵称提示
	        this.showNicknameTip = true
	        
	        // 转换为 base64
	        const base64 = await this.imageToBase64(e.detail.avatarUrl)
	        // 保存 base64 格式
	        this.tempUserInfo.avatarBase64 = base64
	  
	        uni.hideLoading()
	      } catch (error) {
	        uni.hideLoading()
	        console.error('头像处理失败:', error)
	        uni.showToast({
	          title: '头像设置失败',
	          icon: 'none'
	        })
	      }
	    }
	  },
	  
	  // 昵称变更回调
	  async onNicknameChange(e) {
	    const nickname = e.detail.value
	    if (nickname) {
	      this.tempUserInfo.nickname = nickname
	      this.showNicknameTip = false
	  
	      try {
	        uni.showLoading({
	          title: '更新中...'
	        })
	  
	        // 如果有头像和昵称，就更新用户信息
	        if (this.tempUserInfo.avatarBase64 && this.tempUserInfo.nickname) {
	          await this.$store.dispatch('user/updateUserInfo', {
	            ...this.userInfo,
	            avatar: this.tempUserInfo.avatarBase64,
	            nickname: this.tempUserInfo.nickname
	          })
	          
	          uni.hideLoading()
	          uni.showToast({
	            title: '更新成功',
	            icon: 'success'
	          })
	        } else {
	          uni.hideLoading()
	        }
	      } catch (error) {
	        uni.hideLoading()
	        console.error('更新失败:', error)
	        uni.showToast({
	          title: '更新失败',
	          icon: 'none'
	        })
	      }
	    }
	  },
	  
	  // 图片转 base64
	  imageToBase64(filePath) {
	    return new Promise((resolve, reject) => {
	      uni.getFileSystemManager().readFile({
	        filePath,
	        encoding: 'base64',
	        success: (res) => {
	          resolve(`data:image/png;base64,${res.data}`)
	        },
	        fail: reject
	      })
	    })
	  },
	  
    goBack() {
      const pages = getCurrentPages()
      if (pages.length > 1) {
        uni.navigateBack()
      } else {
        uni.switchTab({
          url: '/pages/user/user'
        })
      }
    },

    async loadUserProfile() {
      try {
		const userId = await uni.getStorageSync('token')
        const res = await userApi.getUserProfile(userId)
        if (res.status === 10000 && res.data) {
		  this.tempUserInfo.nickname=res.data.userName
		  this.tempUserInfo.avatarBase64=res.data.image
          this.formData = {
            // avatar: res.data.image,
            // nickname: res.data.userName,
            age: res.data.age,
            company: res.data.company,
            position: res.data.position,
            school: res.data.school,
            introduction: res.data.introduction
          }
          this.isEdit = true
          this.tempUserInfo.avatar = res.data.image
		  this.tempUserInfo.nickname = res.data.userName
          // 设置选择器的索引
          this.ageIndex = this.ageRange.indexOf(parseInt(res.data.age))
        }
      } catch (error) {
        console.log('用户未创建个人信息')
      }
    },

    onAgeChange(e) {
      this.ageIndex = e.detail.value
      this.formData.age = this.ageRange[this.ageIndex]
    },

    validateForm() {
		
		if (!this.tempUserInfo.avatarBase64){
			  uni.showToast({
				title: `请选择头像`,
				icon: 'none'
			  })
			  return false
		}
	
		if (!this.tempUserInfo.nickname){
			  uni.showToast({
				title: `请填写用户名`,
				icon: 'none'
			  })
			  return false
		}
      const requiredFields = {
        age: '年龄',
        company: '公司',
        school: '毕业院校'
      }

      for (const [field, label] of Object.entries(requiredFields)) {
        if (!this.formData[field]) {
          uni.showToast({
            title: `请填写${label}`,
            icon: 'none'
          })
          return false
        }
      }

      return true
    },

    async saveProfile() {
      if (!this.validateForm()) return
      if (this.isSaving) return

      this.isSaving = true
      try {
        // const api = this.isEdit ? userApi.updateProfile : userApi.createProfile
		const userId = await uni.getStorageSync('token')
		const userName = this.tempUserInfo?.nickname
		const image = this.tempUserInfo?.avatarBase64
        const res = await userApi.updateProfile(this.formData, userId, userName, image)
        
        if (res.status === 10000) {
          uni.showToast({
            title: '保存成功',
            icon: 'success'
          })
          setTimeout(() => {
            uni.switchTab({
            	url: '/pages/user/user'
            });
          }, 500)
        }
      } catch (error) {
        uni.showToast({
          title: error.message || '保存失败',
          icon: 'none'
        })
      } finally {
        this.isSaving = false
      }
    }
  }
}
</script>

